            scanning: Bool = false,
            scanFailure: String? = nil
        ) -> WiFiJoinModel {
            let model = WiFiJoinModel(scan: { _ in networks }, join: { _, _, _, _ in })
            model.phase = phase
            model.networks = networks
            model.selected = selected
            model.manualSSID = manualSSID
            model.code = code
            model.isScanning = scanning
